"""60 questões autorais: três variações de cada uma das 20 questões SM1/SM2 enviadas."""
import json, random, sys
from pathlib import Path
root=Path(__file__).resolve().parents[1]
bank=[]
def add(group,base,title,prompt,correct,wrong,explanation,sql='',statements=None):
    options=[correct]+wrong
    assert len(options)==5 and len(set(options))==5
    variant=sum(q['base']==base for q in bank)+1
    random.Random(len(bank)+319).shuffle(options)
    bank.append(dict(id=f'{base}-v{variant}',base=base,group=group,title=title,prompt=prompt,options=options,answer=options.index(correct),explanation=explanation,sql=sql,statements=statements or []))

